const DigitalTwin = React.lazy(() => import('./digital-twin.jsx').then((module) => ({ default: module.DigitalTwin })));

const AuthContext = createContext(null);
const api = async (url, options = {}) => {
  const response = await fetch(url, { credentials: 'include', headers: { 'Content-Type': 'application/json', ...(options.headers || {}) }, ...options });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(data.message || 'Something went wrong.');
  return data;
};
const emailDeliveryNotice = (delivery) => !delivery ? '' : delivery.status === 'sent' ? ' Email sent to the reporter.' : delivery.status === 'opted_out' ? ' Email skipped because the reporter opted out.' : ` Email not delivered: ${delivery.detail || delivery.status}.`;
const readImageFiles = async (files, max = 5) => { const valid = [...(files || [])].slice(0, max).filter((f) => ['image/jpeg', 'image/png', 'image/webp'].includes(f.type) && Number(f.size) <= 2 * 1024 * 1024); const rejected = [...(files || [])].length - valid.length; const attachments = await Promise.all(valid.map((file) => new Promise((resolve) => { const reader = new FileReader(); reader.onload = () => resolve({ name: file.name, type: file.type, size: file.size, data: reader.result }); reader.readAsDataURL(file); }))); return { attachments, rejected }; };

function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  useEffect(() => { api('/api/auth/me').then((data) => setUser(data.user)).catch(() => {}).finally(() => setLoading(false)); }, []);
  return <AuthContext.Provider value={{ user, setUser, loading }}>{children}</AuthContext.Provider>;
}

const useAuth = () => useContext(AuthContext);

